// Tomar el item de entrada
const item = $input.first().json;

// -------------------------
// TELEFONO
// -------------------------
const d = (item.number || "").replace(/\D/g, "");
item.number = d.length >= 10 ? "+549" + d.slice(-10) : "";

// -------------------------
// PAGO
// -------------------------
const pago = (item.pago || "")
  .toString()
  .trim()
  .toLowerCase();

if (pago.includes("pda")) {
  item.pago_id = 69;
} else if (pago.includes("financi")) {
  item.pago_id = 68;
} else {
  item.pago_id = 67;
}

// -------------------------
// ORIGIN SEGÚN FIRST MESSAGE
// -------------------------

// Solo actuar si firtsMessage existe
if (item.firtsMessage !== undefined && item.firtsMessage !== null) {
  const firstMessage = item.firtsMessage
    .toString()
    .trim();

  // Comparación EXACTA
  if (firstMessage === "¡Hola! Quiero más información") {
    item.origin = "G8HZUVJZVRX30WNI9";
  }
}

// -------------------------
// PRODUCTO
// -------------------------
const productoNormalizado = (item.ProductoInteres || "")
  .toString()
  .toLowerCase();

// -------------------------
// MARCAS
// -------------------------
const marcasConfig = {
  renault: { businesstypeid: "4", grupoCaptura: "renault" },
  nissan: { businesstypeid: "5", grupoCaptura: "nissan" },
  jmc: { businesstypeid: "30", grupoCaptura: "jmc" },
  mitsubishi: { businesstypeid: "21", grupoCaptura: "mitsubishi" },
  changan: { businesstypeid: "31", grupoCaptura: "changan" },
  gwm: { businesstypeid: "35", grupoCaptura: "gwm" },
  leapmotor: { businesstypeid: "36", grupoCaptura: "leapmotor" },
  omoda: { businesstypeid: "32", grupoCaptura: "omoda" },
  jaecoo: { businesstypeid: "33", grupoCaptura: "jaecoo" },
  zeekr: { businesstypeid: "38", grupoCaptura: "zeekr" },
  deepal: { businesstypeid: "43", grupoCaptura: "deepal" },
  xpeng: { businesstypeid: "39", grupoCaptura: "xpeng" }
};

// Buscar marca dentro del producto
let marcaEncontrada = null;

for (const marca in marcasConfig) {
  if (productoNormalizado.includes(marca)) {
    marcaEncontrada = marca;
    break;
  }
}

// Actualizar datos de marca si corresponde
if (marcaEncontrada) {
  item.businesstypeid =
    marcasConfig[marcaEncontrada].businesstypeid;

  item.grupoCaptura =
    marcasConfig[marcaEncontrada].grupoCaptura;
}

// -------------------------
// DEVOLVER RESULTADO
// -------------------------
return [
  {
    json: item
  }
];

const item = $('HTTP Request1').first().json;

const asesoresData = $('obtenerAsesores').first().json;
const reglasData = $('obtenerReglas').first().json;

const advisors = asesoresData.data?.users || [];

const reglas = Array.isArray(reglasData.data)
    ? reglasData.data
    : [];

const regla = reglas[0] || null;

const userIds = regla?.configuration?.user_ids || [];
const currentIndex = regla?.current_index ?? 0;

const advisorId = userIds[currentIndex] || null;

const advisor = advisors.find(user =>
    Number(user.id) === Number(advisorId)
);

let numeroVendedor = advisor?.phone || null;

if (numeroVendedor) {
    numeroVendedor = String(numeroVendedor).replace(/\D/g, '');

    if (numeroVendedor.startsWith('0')) {
        numeroVendedor = numeroVendedor.substring(1);
    }

    if (!numeroVendedor.startsWith('549')) {
        numeroVendedor = `549${numeroVendedor}`;
    }
}

item.numero_vendedor = numeroVendedor;

item.asesor_nombre = advisor
    ? `${advisor.first_name || ''} ${advisor.last_name || ''}`.trim()
    : null;

item.asesor_email = advisor?.email || null;

item.sucursal = item.data?.welcome_asigned_branch || null;
item.lead_id = item.data?.welcome_guid || null;

console.log("Asignación de vendedor PDA:", {
    currentIndex,
    userIds,
    advisorId,
    asesorEncontrado: item.asesor_nombre,
    emailEncontrado: item.asesor_email,
    telefonoOriginal: advisor?.phone || null,
    telefonoEncontrado: item.numero_vendedor,
    leadId: item.lead_id
});

return [
    {
        json: item
    }
];

